<template>
  <div class="full-width">
    <div
      v-if="formBuilderConfigModel[fieldName].displayLabelOnLeft"
      :style="'width:' + formBuilderConfigModel[fieldName].labelWidth + '%'"
      class="display-block"
    >
      <div :class="fieldName + '  full-width'">
        {{ getFieldLabel(formBuilderConfigModel[fieldName], '') }}

        <span v-if="false" class="text-red"> * </span>
      </div>
    </div>

    <div
      :style="
        'width:' + getInputFieldWidth(formBuilderConfigModel[fieldName]) + '%'
      "
      class="display-block"
    >
      <div
        class="col-sm-12 col-md-12 col-lg-12 display-flex"
        v-if="!formBuilderConfigModel[fieldName].displayLabelOnLeft"
      >
        <div class="ellipsify" :class="fieldName + ' full-width'">
          {{ getFieldLabel(formBuilderConfigModel[fieldName], '') }}

          <span v-if="false" class="text-red"> * </span>

          <q-tooltip>{{
            getFieldLabel(formBuilderConfigModel[fieldName], '')
          }}</q-tooltip>
        </div>
      </div>

      <div
        :id="fieldName"
        class="col-sm-12 col-md-12 col-lg-12"
        :class="'input-text-28px'"
      >
        <q-select
          outlined
          clearable
          use-input
          :data-field-name="formBuilderConfigModel[fieldName].field_name"
          :options="filteredUserList"
          :disable="isReadOnly || formBuilderConfigModel[fieldName].is_readonly"
          :class="
            'full-width input-field ellipsify' +
            formBuilderConfigModel[fieldName].field_name +
            '_input ' +
            formBuilderConfigModel[fieldName].color +
            ' ' +
            (formBuilderModel[fieldName].input_error ? ' invalid-input ' : '') +
            formBuilderModel[fieldName].input_error
          "
          @update:model-value="
            (new_value: any) => {
              changeEventHandler(new_value);
            }
          "
          v-model="formBuilderModel[fieldName].formatted_value"
          :data-cy="formBuilderModel[fieldName].field_name"
          emit-value
          map-options
          @filter="eventFilterUserList"
          :loading="user_list_loading"
        >
          <template v-slot:selected-item="scope">
            <div class="ellipsify">
              {{ resolveSelectedLabel(scope.opt) }}
            </div>
          </template>
          <template v-slot:append>
            <!-- error icon -->
            <div class="inner-field-actions" style="height: 38px">
              <q-icon
                v-if="formBuilderModel[fieldName].input_error"
                flat
                dense
                name="error"
                size="24px"
                color="red"
              >
                <q-tooltip class="bg-red line-error-tooltip">
                  <template
                    v-if="formBuilderModel[fieldName].input_error !== ''"
                  >
                    {{ $t(formBuilderModel[fieldName].input_error) }}
                  </template>
                </q-tooltip>
              </q-icon>

              <q-badge
                v-if="isFormBuilderMode && showTabIndex"
                color="orange"
                text-color="black"
                :label="formBuilderConfigModel[fieldName].tabIndex"
              />
            </div>
          </template>
        </q-select>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import intUtils from 'src/utils/int';
import { defineComponent, ref } from 'vue';
import { CONSTANTS } from 'src/constants';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import validation_mixin from 'src/validatior/validation_mixin';
import formBuilderHelper from 'src/formBuilder/utils/formBuilderHelper';
import { resolveSelectedItemLabel } from 'src/utils/approverName';
import {
  useFormBuilderStore,
  useDropdownStore,
  useDocumentStore,
} from 'src/store/main';

export default defineComponent({
  name: 'DocumentApprover',
  components: {},
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    groupIndex: {
      type: Number,
      default: 0,
    },
  },
  emits: ['inputClicked', 'inputValueChanges', 'updateModel'],
  mixins: [displayFieldLabel, formBuilderHelper, validation_mixin, intUtils],
  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  mounted: function () {
    this.init();
  },
  unmounted: function () {
    // nothing to do
  },
  methods: {
    async init() {
      if (this.isFormBuilderMode) {
        return;
      }
      await this.prepareUsersDropdown();
      this.filteredUserList = this.usersList;
    },

    // SEF-277: resolve the selected approver id to a name with a
    // String()-normalized lookup so a string id (e.g. "42") still matches the
    // numeric usersList option (42). Never renders a raw id — falls back to ''.
    resolveSelectedLabel(opt: any): string {
      return resolveSelectedItemLabel(opt, this.usersList);
    },

    filertByAssignedToKey(val: string) {
      const needle = val.toLowerCase();
      this.filteredUserList = this.usersList.filter(
        (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
      );
    },

    changeEventHandler(new_value: any) {
      this.formBuilderModel[this.fieldName].formatted_value = new_value;
      this.formBuilderModel[this.fieldName].value = new_value;
      this.formBuilderModel[this.fieldName].input_error = '';
      this.formBuilderConfigModel[this.fieldName].color =
        CONSTANTS.success_border_left;
      this.record.assigned_to = new_value;
      this.$emit('inputValueChanges', this.fieldName, 'input');
    },

    eventFilterUserList(val: string, update: any, abort: any) {
      try {
        if (val === '') {
          update(() => {
            this.filteredUserList = this.usersList;
          });
          return;
        }

        update(() => {
          this.filertByAssignedToKey(val);
        });
      } catch (err) {
        logError(err);
        abort();
      }
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      second_approval,
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      showTabIndex,
    } = storeToRefs(form_builder_store);

    const dropdown_store = useDropdownStore();
    const filteredUserList: any = ref(dropdown_store.usersList);

    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    const { prepareUsersDropdown } = dropdown_store;
    const { user_list_loading, usersList } = storeToRefs(dropdown_store);

    return {
      prepareUsersDropdown,
      record,
      usersList,
      filteredUserList,
      user_list_loading,

      showTabIndex,
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      second_approval,
    };
  },
});
</script>
<style lang="scss" scoped></style>
