<template>

  <div class="full-width" :class="isFormBuilderMode && showTabIndex ? 'position-relative' : ''">
    <q-checkbox :id="fieldName" child_type="checkbox" :disable="isReadOnly || formBuilderConfigModel[fieldName].is_readonly"
        :tabindex="formBuilderConfigModel[fieldName].tabIndex"
        :label="getFieldLabel(formBuilderConfigModel[fieldName], '')"
        @focus="focusEvent"
        @keydown.enter="keydownEvent"
        v-model="formBuilderModel[fieldName].formatted_value" @update:model-value="inputValueChanges($event, fieldName)" size="30px" color="grey-6" 
        :class="(formBuilderModel[fieldName].name) + ' ' + (getElementBorder(formBuilderConfigModel[fieldName].color))" >

    </q-checkbox>
    <q-badge
      v-if="isFormBuilderMode && showTabIndex"
      color="orange"
      text-color="black"
      :class="isFormBuilderMode && showTabIndex ? 'checkbox-badge' : ''"
      :label="formBuilderConfigModel[fieldName].tabIndex"
    />
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import documentUtil from 'src/utils/documentUtil';
import { useFormBuilderStore } from 'src/store/main';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import formBuilderHelper from 'src/formBuilder/utils/formBuilderHelper';

export default defineComponent({
  name: 'CheckBox',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['inputValueChanges', 'updateModel'],
  mixins: [displayFieldLabel, formBuilderHelper, documentUtil],

  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  methods: {
    getLowerConfidence(field: any): any {
      if (this.isFormBuilderMode) {
        return null;
      }
      return this.getLowerConfidence(field);
    },

    inputValueChanges(e: any, fieldName: string) {
      const is_entered_pressed = (<any>window).event.key == 'Enter';
      if (is_entered_pressed) {
        this.formBuilderModel[this.fieldName].formatted_value =
          !this.formBuilderModel[this.fieldName].formatted_value;
        this.triggerMoveToNextFieldEvent();
        return;
      }

      this.$emit('inputValueChanges', fieldName, 'checkbox');
    },

    triggerMoveToNextFieldEvent() {
      if (this.is_focus_event) {
        this.is_focus_event = false;
        return;
      }
      const event = new CustomEvent('move_to_next_field', {
        detail: this.fieldName,
      });
      document.dispatchEvent(event);
    },

    keydownEvent(e: any) {
      this.is_focus_event = false;
      this.triggerMoveToNextFieldEvent();
    },

    focusEvent(e: any) {
      this.is_focus_event = true;
      setTimeout(() => {
        this.is_focus_event = false;
      }, 500);
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      showTabIndex,
    } = storeToRefs(form_builder_store);
    return {
      formBuilderConfigModel,
      isFormBuilderMode,
      formBuilderModel,
      is_focus_event: ref(false),
      showTabIndex,
    };
  },
});
</script>
