<template>
  <q-separator
    class="cursor-pointer"
    :size="formBuilderConfigModel[fieldName].size + 'px'"
    :style="'background-color:' + formBuilderConfigModel[fieldName].color"
    :class="
      formBuilderConfigModel[fieldName].space_from_top +
      ' ' +
      formBuilderConfigModel[fieldName].space_from_bottom
    "
    @click="$emit('inputClicked', fieldName)"
  />
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useFormBuilderStore } from 'src/store/main';

export default defineComponent({
  name: 'HorizontalSeparator',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['updateModel', 'inputClicked'],
  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  methods: {},
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { isFormBuilderMode, formBuilderConfigModel } =
      storeToRefs(form_builder_store);
    return {
      isFormBuilderMode,
      formBuilderConfigModel,
    };
  },
});
</script>
